/// The synthetic dataset the app ships with, and the records it materialises.
///
/// Generated by `mobileapp/tools/export_demo_dataset.py`. Every record stores a
/// day offset rather than a timestamp, and the dates are computed against the
/// current clock when the asset is loaded. An APK built in September would
/// otherwise be showing September cases at Christmas, with an empty "last 7
/// days" window - stale in exactly the way that makes a demo look dead.
///
/// Nothing here is presented as real. Cases carry `model_version: demo-seed`
/// and farmer names starting "Demo", and the API marks every response
/// `demo: true`, so a demo row can always be told from a field report.
library;

import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

const String kDemoAsset = 'assets/demo/dataset.json';

class DemoCase {
  DemoCase({
    required this.id,
    required this.createdAt,
    required this.source,
    required this.farmerName,
    required this.crop,
    required this.variety,
    required this.cropStage,
    required this.soilCondition,
    required this.district,
    required this.village,
    required this.latitude,
    required this.longitude,
    required this.geoCell,
    required this.predictedClass,
    required this.confidence,
    required this.modelVersion,
    required this.riskLevel,
    required this.riskScore,
    required this.escalate,
    required this.escalationReasons,
    required this.language,
    required this.reviewStatus,
    required this.confirmedClass,
    required this.reviewer,
    required this.reviewerNotes,
    required this.reviewedAt,
  });

  final int id;
  final DateTime createdAt;
  final String source;
  final String farmerName;
  final String crop;
  final String variety;
  final String cropStage;
  final String soilCondition;
  final String district;
  final String village;
  final double latitude;
  final double longitude;
  final String? geoCell;
  final String predictedClass;
  final double confidence;
  final String modelVersion;
  final String riskLevel;
  final double riskScore;
  final bool escalate;
  final List<Map<String, dynamic>> escalationReasons;
  final String language;
  final String reviewStatus;
  final String? confirmedClass;
  final String? reviewer;
  final String? reviewerNotes;
  final DateTime? reviewedAt;

  /// The expert's label where one exists, the model's otherwise. This is the
  /// same rule `Case.effective_class` uses on the server: a corrected case must
  /// count towards what it actually was, not what the model guessed.
  String get effectiveClass => confirmedClass ?? predictedClass;

  bool get isReviewed =>
      reviewStatus == 'confirmed' || reviewStatus == 'corrected';

  static DemoCase fromJson(Map<String, dynamic> j, DateTime now) {
    final created = now.subtract(Duration(
      days: (j['day_offset'] as num).toInt(),
      hours: (j['hour'] as num).toInt(),
    ));
    final reviewedAfter = (j['reviewed_after_days'] as num?)?.toInt();
    return DemoCase(
      id: (j['id'] as num).toInt(),
      createdAt: created,
      source: j['source'] as String,
      farmerName: j['farmer_name'] as String,
      crop: j['crop'] as String,
      variety: j['variety'] as String,
      cropStage: j['crop_stage'] as String,
      soilCondition: j['soil_condition'] as String,
      district: j['district'] as String,
      village: j['village'] as String,
      latitude: (j['latitude'] as num).toDouble(),
      longitude: (j['longitude'] as num).toDouble(),
      geoCell: j['geo_cell'] as String?,
      predictedClass: j['predicted_class'] as String,
      confidence: (j['confidence'] as num).toDouble(),
      modelVersion: j['model_version'] as String,
      riskLevel: j['risk_level'] as String,
      riskScore: (j['risk_score'] as num).toDouble(),
      escalate: j['escalate'] as bool,
      escalationReasons: ((j['escalation_reasons'] as List?) ?? const [])
          .map((e) => (e as Map).cast<String, dynamic>())
          .toList(),
      language: j['language'] as String,
      reviewStatus: j['review_status'] as String,
      confirmedClass: j['confirmed_class'] as String?,
      reviewer: j['reviewer'] as String?,
      reviewerNotes: j['reviewer_notes'] as String?,
      reviewedAt:
          reviewedAfter == null ? null : created.add(Duration(days: reviewedAfter)),
    );
  }

  /// The `CaseOut` shape the web UI expects. Field names are the server's,
  /// because the same React pages render both.
  Map<String, dynamic> toJson() => {
        'id': id,
        'created_at': createdAt.toIso8601String(),
        'source': source,
        'farmer_name': farmerName,
        'phone': null,
        'crop': crop,
        'variety': variety,
        'crop_stage': cropStage,
        'soil_condition': soilCondition,
        'district': district,
        'village': village,
        'latitude': latitude,
        'longitude': longitude,
        'geo_cell': geoCell,
        'image_path': null,
        'predicted_class': predictedClass,
        'confidence': confidence,
        'detections': const [],
        'model_version': modelVersion,
        'risk_level': riskLevel,
        'risk_score': riskScore,
        'escalate': escalate,
        'escalation_reasons': escalationReasons,
        'language': language,
        'review_status': reviewStatus,
        'confirmed_class': confirmedClass,
        'reviewer': reviewer,
        'reviewer_notes': reviewerNotes,
        'reviewed_at': reviewedAt?.toIso8601String(),
        'demo': true,
      };
}

class DemoFollowUp {
  DemoFollowUp({
    required this.id,
    required this.caseId,
    required this.createdAt,
    required this.dueDate,
    required this.notes,
    required this.outcome,
    required this.treatmentApplied,
    required this.closedAt,
  });

  final int id;
  final int caseId;
  final DateTime createdAt;
  final DateTime dueDate;
  final String notes;
  final String outcome;
  final String? treatmentApplied;
  final DateTime? closedAt;

  bool get isPending => outcome == 'pending';

  static DemoFollowUp fromJson(Map<String, dynamic> j, DateTime now) {
    final created = now.subtract(Duration(days: (j['day_offset'] as num).toInt()));
    final closedAfter = (j['closed_after_days'] as num?)?.toInt();
    return DemoFollowUp(
      id: (j['id'] as num).toInt(),
      caseId: (j['case_id'] as num).toInt(),
      createdAt: created,
      dueDate: created.add(Duration(days: (j['due_after_days'] as num).toInt())),
      notes: j['notes'] as String,
      outcome: j['outcome'] as String,
      treatmentApplied: j['treatment_applied'] as String?,
      closedAt:
          closedAfter == null ? null : created.add(Duration(days: closedAfter)),
    );
  }

  Map<String, dynamic> toJson() => {
        'id': id,
        'case_id': caseId,
        'created_at': createdAt.toIso8601String(),
        'due_date': dueDate.toIso8601String(),
        'notes': notes,
        'outcome': outcome,
        'treatment_applied': treatmentApplied,
        'closed_at': closedAt?.toIso8601String(),
        'demo': true,
      };
}

class DemoReading {
  DemoReading({
    required this.deviceId,
    required this.deviceType,
    required this.metric,
    required this.value,
    required this.unit,
    required this.crop,
    required this.district,
    required this.latitude,
    required this.longitude,
    required this.geoCell,
    required this.recordedAt,
  });

  final String deviceId;
  final String deviceType;
  final String metric;
  final double value;
  final String unit;
  final String crop;
  final String district;
  final double latitude;
  final double longitude;
  final String? geoCell;
  final DateTime recordedAt;

  static DemoReading fromJson(Map<String, dynamic> j, DateTime now) => DemoReading(
        deviceId: j['device_id'] as String,
        deviceType: j['device_type'] as String,
        metric: j['metric'] as String,
        value: (j['value'] as num).toDouble(),
        unit: j['unit'] as String,
        crop: j['crop'] as String,
        district: j['district'] as String,
        latitude: (j['latitude'] as num).toDouble(),
        longitude: (j['longitude'] as num).toDouble(),
        geoCell: j['geo_cell'] as String?,
        recordedAt:
            now.subtract(Duration(days: (j['day_offset'] as num).toInt())),
      );

  Map<String, dynamic> toJson() => {
        'device_id': deviceId,
        'device_type': deviceType,
        'metric': metric,
        'value': value,
        'unit': unit,
        'crop': crop,
        'district': district,
        'latitude': latitude,
        'longitude': longitude,
        'geo_cell': geoCell,
        'recorded_at': recordedAt.toIso8601String(),
        'demo': true,
      };
}

/// The loaded dataset. Held for the life of the process: 120 cases is nothing
/// in memory, and re-parsing 293 KB of JSON per request would be visible.
class DemoDataset {
  DemoDataset({
    required this.cases,
    required this.followUps,
    required this.readings,
    required this.loadedAt,
  });

  final List<DemoCase> cases;
  final List<DemoFollowUp> followUps;
  final List<DemoReading> readings;
  final DateTime loadedAt;

  static DemoDataset? _cached;

  /// Parses the bundled asset. Returns an empty dataset rather than throwing if
  /// the asset is missing, so a build without it degrades to the live-only view
  /// instead of failing every officer endpoint.
  static Future<DemoDataset> load({DateTime? now}) async {
    if (_cached != null) return _cached!;
    final when = now ?? DateTime.now().toUtc();
    try {
      final raw = await rootBundle.loadString(kDemoAsset);
      _cached = fromJson(
        jsonDecode(raw) as Map<String, dynamic>,
        when,
      );
    } catch (_) {
      _cached = DemoDataset(
        cases: const [],
        followUps: const [],
        readings: const [],
        loadedAt: when,
      );
    }
    return _cached!;
  }

  static DemoDataset fromJson(Map<String, dynamic> j, DateTime now) => DemoDataset(
        cases: ((j['cases'] as List?) ?? const [])
            .map((c) => DemoCase.fromJson((c as Map).cast<String, dynamic>(), now))
            .toList(),
        followUps: ((j['follow_ups'] as List?) ?? const [])
            .map((f) =>
                DemoFollowUp.fromJson((f as Map).cast<String, dynamic>(), now))
            .toList(),
        readings: ((j['sensor_readings'] as List?) ?? const [])
            .map((r) =>
                DemoReading.fromJson((r as Map).cast<String, dynamic>(), now))
            .toList(),
        loadedAt: now,
      );

  bool get isEmpty => cases.isEmpty;

  /// Cases inside the window, optionally one district. The window is the
  /// dashboard's period selector, which is why it has to be applied here
  /// rather than baked into the asset.
  List<DemoCase> casesWithin(int days, {String? district}) {
    final since = loadedAt.subtract(Duration(days: days));
    return [
      for (final c in cases)
        if (!c.createdAt.isBefore(since) &&
            (district == null || district.isEmpty || c.district == district))
          c
    ];
  }
}
